import React, { useState } from 'react';
import API from '../api';

const CreateFranchise = () => {
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    contactNumber: '',
    status: 'active', // Default value
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await API.post('/franchises', formData);
      alert('Franchise created successfully!');
      console.log('Response:', response.data); // Debugging: Log response
    } catch (error) {
      alert('Error creating franchise: ' + error.response?.data?.message || error.message);
      console.error('Error:', error); // Debugging: Log error
    }
  };

  return (
    <div>
      <h1>Create Franchise</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Franchise Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="location">Location:</label>
          <input
            id="location"
            name="location"
            placeholder="Franchise Location"
            value={formData.location}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="contactNumber">Contact Number:</label>
          <input
            id="contactNumber"
            name="contactNumber"
            placeholder="Contact Number"
            value={formData.contactNumber}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="status">Status:</label>
          <select id="status" name="status" value={formData.status} onChange={handleChange}>
            <option value="active">Active</option>
            <option value="inactive">Inactive</option>
          </select>
        </div>
        <button type="submit">Create Franchise</button>
      </form>
    </div>
  );
};

export default CreateFranchise;
